using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Text;
namespace BorderlessDesk;
static class Program {
 [STAThread] static void Main(string[] args) { ApplicationConfiguration.Initialize(); if(args.Contains("--self-test")){ SelfTest.Run(); return; } Application.Run(new MainForm()); }
}
record WindowItem(nint Handle,uint Pid,string Title,string Process) { public override string ToString()=>Title; }
class Snapshot { public required WindowItem Item; public long Style,ExStyle; public Native.Placement Placement; public Rectangle Target; public bool Maintain; }
static class Native {
 public delegate bool EnumProc(nint h,nint l);
 [StructLayout(LayoutKind.Sequential)] public struct Rect {public int Left,Top,Right,Bottom;}
 [StructLayout(LayoutKind.Sequential)] public struct Point {public int X,Y;}
 [StructLayout(LayoutKind.Sequential)] public struct Placement {public int Length,Flags,Show;public Point Min,Max;public Rect Normal;}
 [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc p,nint l);
 [DllImport("user32.dll")] public static extern bool IsWindowVisible(nint h);
 [DllImport("user32.dll")] public static extern bool IsWindow(nint h);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)] public static extern int GetWindowText(nint h,StringBuilder s,int n);
 [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(nint h,out uint p);
 [DllImport("user32.dll",EntryPoint="GetWindowLongPtrW")] public static extern nint GetLong(nint h,int i);
 [DllImport("user32.dll",EntryPoint="SetWindowLongPtrW",SetLastError=true)] public static extern nint SetLong(nint h,int i,nint v);
 [DllImport("user32.dll",SetLastError=true)] public static extern bool SetWindowPos(nint h,nint after,int x,int y,int w,int height,uint flags);
 [DllImport("user32.dll")] public static extern bool GetWindowRect(nint h,out Rect r);
 [DllImport("user32.dll")] public static extern bool GetWindowPlacement(nint h,ref Placement p);
 [DllImport("user32.dll")] public static extern bool SetWindowPlacement(nint h,ref Placement p);
 [DllImport("user32.dll")] public static extern bool ShowWindow(nint h,int n);
 [DllImport("dwmapi.dll")] static extern int DwmGetWindowAttribute(nint h,int attr,out int value,int size);
 public static List<WindowItem> Windows(){var list=new List<WindowItem>(); EnumWindows((h,l)=>{ if(!IsWindowVisible(h))return true; var b=new StringBuilder(1024);GetWindowText(h,b,b.Capacity);if(b.Length==0||b.ToString()=="Program Manager")return true;GetWindowThreadProcessId(h,out var pid);if(pid==Environment.ProcessId)return true; if(DwmGetWindowAttribute(h,14,out var cloaked,4)==0&&cloaked!=0)return true;string name;try{name=Process.GetProcessById((int)pid).ProcessName;}catch{name="알 수 없음";}list.Add(new(h,pid,b.ToString(),name));return true;},0);return list.OrderBy(x=>x.Process).ToList();}
 public static bool Alive(WindowItem i)=>IsWindow(i.Handle)&&GetWindowThreadProcessId(i.Handle,out var p)!=0&&p==i.Pid;
 public static Snapshot Capture(WindowItem i,Rectangle target,bool maintain){var p=new Placement{Length=Marshal.SizeOf<Placement>()};if(!Alive(i)||!GetWindowPlacement(i.Handle,ref p))throw new Exception("대상 창이 종료되었거나 접근할 수 없습니다.");return new(){Item=i,Style=(long)GetLong(i.Handle,-16),ExStyle=(long)GetLong(i.Handle,-20),Placement=p,Target=target,Maintain=maintain};}
 public static void Apply(Snapshot s){if(!Alive(s.Item))throw new Exception("대상 창이 종료되었습니다.");var h=s.Item.Handle;ShowWindow(h,9);Write(h,-16,(long)GetLong(h,-16)&~0x00CF0000L);Write(h,-20,(long)GetLong(h,-20)&~0x00020301L);var r=s.Target;if(!SetWindowPos(h,0,r.X,r.Y,r.Width,r.Height,0x0034))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());}
 static void Write(nint h,int i,long v){Marshal.SetLastPInvokeError(0);var result=SetLong(h,i,(nint)v);if(result==0&&Marshal.GetLastWin32Error()!=0)throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());}
 public static bool NeedsApply(Snapshot s){GetWindowRect(s.Item.Handle,out var r);return ((long)GetLong(s.Item.Handle,-16)&0x00CF0000L)!=0||r.Left!=s.Target.Left||r.Top!=s.Target.Top||r.Right!=s.Target.Right||r.Bottom!=s.Target.Bottom;}
 public static void Restore(Snapshot s){if(!Alive(s.Item))return;Write(s.Item.Handle,-16,s.Style);Write(s.Item.Handle,-20,s.ExStyle);var p=s.Placement;if(!SetWindowPlacement(s.Item.Handle,ref p)||!SetWindowPos(s.Item.Handle,0,0,0,0,0,0x0037))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());}
}
class MainForm:Form {
 readonly ListView list=new();readonly TextBox search=new();readonly ComboBox monitors=new();readonly CheckBox auto=new(){Text="자동 유지 (게임이 창 크기를 되돌려도 재적용)",Checked=true,AutoSize=true};readonly Label status=new(){AutoSize=true};readonly Dictionary<nint,Snapshot> changed=new();readonly NotifyIcon tray=new();readonly System.Windows.Forms.Timer timer=new(){Interval=1000};bool exiting;
 public MainForm(){Text="Borderless Desk";Size=new(980,640);MinimumSize=new(780,520);StartPosition=FormStartPosition.CenterScreen;BackColor=Color.FromArgb(20,23,30);ForeColor=Color.FromArgb(225,230,240);Font=new("맑은 고딕",10);Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath) ?? SystemIcons.Application;
 var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new(24),ColumnCount=1,RowCount=6};root.RowStyles.Add(new(SizeType.Absolute,74));root.RowStyles.Add(new(SizeType.Absolute,42));root.RowStyles.Add(new(SizeType.Percent,100));root.RowStyles.Add(new(SizeType.Absolute,48));root.RowStyles.Add(new(SizeType.Absolute,52));root.RowStyles.Add(new(SizeType.Absolute,44));Controls.Add(root);
 var heading=new Label{Text="BORDERLESS DESK\n실행 중인 창을 선택해 테두리 없는 전체창으로 전환",Dock=DockStyle.Fill,Font=new("맑은 고딕",13,FontStyle.Bold)};root.Controls.Add(heading);
 search.PlaceholderText="창 제목 또는 프로그램 검색";search.Dock=DockStyle.Fill;search.BackColor=Color.FromArgb(32,37,47);search.ForeColor=ForeColor;search.TextChanged+=(_,_)=>RefreshWindows();root.Controls.Add(search);
 list.Dock=DockStyle.Fill;list.View=View.Details;list.FullRowSelect=true;list.MultiSelect=false;list.HideSelection=false;list.BackColor=Color.FromArgb(27,31,40);list.ForeColor=ForeColor;list.BorderStyle=BorderStyle.None;list.OwnerDraw=true;list.DrawColumnHeader+=(_,e)=>{using var brush=new SolidBrush(Color.FromArgb(40,46,60));e.Graphics.FillRectangle(brush,e.Bounds);TextRenderer.DrawText(e.Graphics,e.Header!.Text,Font,e.Bounds,ForeColor,TextFormatFlags.Left|TextFormatFlags.VerticalCenter);};list.DrawItem+=(_,e)=>e.DrawDefault=true;list.DrawSubItem+=(_,e)=>e.DrawDefault=true;list.SelectedIndexChanged+=(_,_)=>{if(Selected() is {} item&&changed.TryGetValue(item.Handle,out var snap))auto.Checked=snap.Maintain;};list.Columns.Add("프로그램",170);list.Columns.Add("창 제목",470);list.Columns.Add("상태",160);root.Controls.Add(list);
 var opts=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new(0,8,0,0)};monitors.DropDownStyle=ComboBoxStyle.DropDownList;monitors.Width=330;monitors.BackColor=search.BackColor;monitors.ForeColor=ForeColor;foreach(var s in Screen.AllScreens)monitors.Items.Add($"{s.DeviceName} · {s.Bounds.Width} × {s.Bounds.Height}{(s.Primary?" · 주 모니터":"")}");monitors.SelectedIndex=0;opts.Controls.Add(monitors);opts.Controls.Add(auto);auto.CheckedChanged+=(_,_)=>{if(Selected() is {} i&&changed.TryGetValue(i.Handle,out var s))s.Maintain=auto.Checked;};root.Controls.Add(opts);
 var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill};buttons.Controls.Add(Button("전체창 적용",ApplySelected,true));buttons.Controls.Add(Button("선택 창 복원",RestoreSelected));buttons.Controls.Add(Button("목록 새로고침",RefreshWindows));buttons.Controls.Add(Button("모두 복원",()=>RestoreAll()));root.Controls.Add(buttons);status.Text="대상 프로그램을 창 모드로 실행한 뒤 적용하세요. X: 트레이로 숨김";root.Controls.Add(status);
 var menu=new ContextMenuStrip();menu.Items.Add("프로그램 열기",null,(_,_)=>{Show();WindowState=FormWindowState.Normal;Activate();});menu.Items.Add("모두 복원",null,(_,_)=>RestoreAll());menu.Items.Add("복원 후 종료",null,(_,_)=>{if(RestoreAll()){exiting=true;Close();}});tray.Icon=Icon;tray.Text="Borderless Desk";tray.ContextMenuStrip=menu;tray.Visible=true;tray.DoubleClick+=(_,_)=>{Show();Activate();};FormClosing+=(_,e)=>{if(!exiting){e.Cancel=true;Hide();tray.ShowBalloonTip(2000,"Borderless Desk","전체창 기능은 계속 실행됩니다. 트레이 메뉴에서 종료할 수 있습니다.",ToolTipIcon.Info);}};FormClosed+=(_,_)=>{timer.Stop();tray.Dispose();};timer.Tick+=(_,_)=>Maintain();timer.Start();RefreshWindows();}
 Button Button(string text,Action action,bool primary=false){var b=new Button{Text=text,AutoSize=true,Height=38,FlatStyle=FlatStyle.Flat,BackColor=primary?Color.FromArgb(65,102,220):Color.FromArgb(40,46,60),ForeColor=ForeColor,Padding=new(12,4,12,4)};b.FlatAppearance.BorderSize=0;b.Click+=(_,_)=>action();return b;}
 WindowItem? Selected()=>list.SelectedItems.Count==0?null:list.SelectedItems[0].Tag as WindowItem;
 void RefreshWindows(){var selected=Selected()?.Handle;list.BeginUpdate();list.Items.Clear();foreach(var i in Native.Windows().Where(i=>(i.Title+" "+i.Process).Contains(search.Text,StringComparison.OrdinalIgnoreCase))){var row=new ListViewItem(new[]{i.Process,i.Title,changed.ContainsKey(i.Handle)?"전체창 적용됨":"창"}){Tag=i};list.Items.Add(row);if(selected==i.Handle)row.Selected=true;}list.EndUpdate();}
 void ApplySelected(){if(Selected() is not {} i){status.Text="대상 창을 먼저 선택하세요.";return;}try{if(!changed.TryGetValue(i.Handle,out var s)){s=Native.Capture(i,Screen.AllScreens[monitors.SelectedIndex].Bounds,auto.Checked);changed.Add(i.Handle,s);}s.Target=Screen.AllScreens[monitors.SelectedIndex].Bounds;s.Maintain=auto.Checked;Native.Apply(s);status.Text=$"적용 완료: {i.Process}";RefreshWindows();}catch(Exception e){status.Text="적용 실패: "+e.Message+" 관리자 프로그램은 동일 권한으로 실행하세요.";}}
 void RestoreSelected(){if(Selected() is {} i&&changed.TryGetValue(i.Handle,out var s)){try{Native.Restore(s);changed.Remove(i.Handle);status.Text="선택 창 복원 완료";RefreshWindows();}catch(Exception e){status.Text="복원 실패: "+e.Message;}}}
 bool RestoreAll(){bool ok=true;foreach(var pair in changed.ToArray()){try{Native.Restore(pair.Value);changed.Remove(pair.Key);}catch(Exception e){ok=false;status.Text="복원 실패: "+e.Message;}}RefreshWindows();if(ok)status.Text="모든 창 복원 완료";return ok;}
 void Maintain(){foreach(var pair in changed.ToArray()){var s=pair.Value;if(!Native.Alive(s.Item)){changed.Remove(pair.Key);continue;}if(!s.Maintain)continue;try{if(Native.NeedsApply(s))Native.Apply(s);}catch(Exception e){s.Maintain=false;status.Text="자동 유지 중단: "+e.Message;}}}
}
static class SelfTest {
 public static void Run(){var lines=new List<string>();try{using var f=new Form{Text="BorderlessDesk test",Bounds=new(120,140,420,310)};f.Show();Application.DoEvents();var i=new WindowItem(f.Handle,(uint)Environment.ProcessId,f.Text,"test");var s=Native.Capture(i,Screen.PrimaryScreen!.Bounds,true);Native.Apply(s);if(Native.NeedsApply(s))throw new Exception("Fullscreen geometry/style mismatch");lines.Add("PASS: fullscreen geometry and border removal");Native.SetWindowPos(f.Handle,0,100,100,300,200,0x14);if(!Native.NeedsApply(s))throw new Exception("Maintenance detection failed");Native.Apply(s);if(Native.NeedsApply(s))throw new Exception("Maintenance reapply failed");lines.Add("PASS: automatic maintenance detection and reapply");Native.Restore(s);if((long)Native.GetLong(f.Handle,-16)!=s.Style||(long)Native.GetLong(f.Handle,-20)!=s.ExStyle)throw new Exception("Restore style mismatch");var p=new Native.Placement{Length=Marshal.SizeOf<Native.Placement>()};Native.GetWindowPlacement(f.Handle,ref p);if(p.Normal.Left!=s.Placement.Normal.Left||p.Normal.Top!=s.Placement.Normal.Top||p.Normal.Right!=s.Placement.Normal.Right||p.Normal.Bottom!=s.Placement.Normal.Bottom)throw new Exception("Restore placement mismatch");lines.Add("PASS: original styles and placement restored");using var ui=new MainForm();ui.Show();Application.DoEvents();using var bitmap=new Bitmap(ui.Width,ui.Height);ui.DrawToBitmap(bitmap,new Rectangle(Point.Empty,ui.Size));bitmap.Save(Path.Combine(AppContext.BaseDirectory,"ui-preview.png"));lines.Add("PASS: dark UI constructed and rendered");}catch(Exception e){lines.Add("FAIL: "+e);Environment.ExitCode=1;}File.WriteAllLines(Path.Combine(AppContext.BaseDirectory,"self-test.txt"),lines);}
}



